public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int result = 0;

    // Traverse the matrix, keep track of the up, down, left, and right count
    // of the current line of 1s.
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int up = 0, down = 0, left = 0, right = 0;
                // Traverse up
                for (int k = i - 1; k >= 0; k--) {
                    if (mat[k][j] == 0) break;
                    up++;
                }

                // Traverse down
                for (int k = i + 1; k < m; k++) {
                    if (mat[k][j] == 0) break;
                    down++;
                }

                // Traverse left
                for (int k = j - 1; k >= 0; k--) {
                    if (mat[i][k] == 0) break;
                    left++;
                }

                // Traverse right
                for (int k = j + 1; k < n; k++) {
                    if (mat[i][k] == 0) break;
                    right++;
                }

                // Update the max length
                result = Math.max(result, up + down + left + right + 1);
            }
        }
    }

    return result;
}
