    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int height = heights[i];
        int currentArea = height;
        for (int j = i + 1; j < n && heights[j] >= heights[i]; j++) {
            currentArea = Math.max(currentArea, height * (j - i + 1));
        }
        maxArea = Math.max(maxArea, currentArea);
    }
    return maxArea;
