public static int calculateUniqueSum(int[] nums) {

  Set&lt;Integer&gt; uniqueSet = new HashSet&lt;Integer&gt;();

  for (int num : nums) {
      if (!uniqueSet.contains(num)) {
          uniqueSet.add(num);
      }
  }
  int sum = 0;
  for (int uniqueNum : uniqueSet) {
      sum += uniqueNum;
  }
  return sum;
}

